import data from "@/data/videos.json";

// Video types plus the file-based manifest generated by
// scripts/prepare-videos.mjs (the fallback and database seed). Live,
// dashboard-editable videos are read through src/lib/data/videos.ts.

export type VideoKind = "film" | "reel" | "logo";

export interface Video {
  id: string;
  kind: VideoKind;
  /** Full video with sound (H.264/AAC MP4). */
  src: string;
  /** Short, silent loop used for autoplaying previews (may be the full video). */
  preview: string;
  poster: string;
  w: number;
  h: number;
  /** Seconds. */
  duration: number;
  title?: string;
  tag?: string;
}

export const FILE_VIDEOS = (data as { videos: Video[] }).videos;

/** 81 → "1:21". */
export function formatDuration(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = Math.round(seconds % 60);
  return `${m}:${String(s).padStart(2, "0")}`;
}
